function obterIdentidadeVisitante() {
    const chaveCor = 'pagina-flutuante-visitante';
    const chaveId = 'pagina-flutuante-visitante-id';
    let hue;
    let visitorId;
    try {
        const salvo = Number(localStorage.getItem(chaveCor));
        if (Number.isInteger(salvo) && salvo >= 0 && salvo <= 359) hue = salvo;
        visitorId = localStorage.getItem(chaveId);
    } catch (error) {
        console.warn('Não foi possível recuperar a identidade persistente deste navegador.', error);
    }

    if (!Number.isInteger(hue)) hue = Math.floor(Math.random() * 360);
    if (!visitorId || !/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(visitorId)) {
        const bytes = new Uint8Array(16);
        if (window.crypto?.getRandomValues) {
            window.crypto.getRandomValues(bytes);
        } else {
            for (let i = 0; i < bytes.length; i++) bytes[i] = Math.floor(Math.random() * 256);
        }
        bytes[6] = (bytes[6] & 0x0f) | 0x40;
        bytes[8] = (bytes[8] & 0x3f) | 0x80;
        const hexadecimal = Array.from(bytes, byte => byte.toString(16).padStart(2, '0')).join('');
        visitorId = `${hexadecimal.slice(0, 8)}-${hexadecimal.slice(8, 12)}-${hexadecimal.slice(12, 16)}-${hexadecimal.slice(16, 20)}-${hexadecimal.slice(20)}`;
    }

    try {
        localStorage.setItem(chaveCor, String(hue));
        localStorage.setItem(chaveId, visitorId);
    } catch (error) {
        console.warn('Não foi possível guardar a identidade persistente deste navegador.', error);
    }
    return { id: visitorId, hue };
}

function tocarSomTransicaoFinal() {
    somPendente = true;
    if (!audioPreparado) return;

    somTransicaoFinal.currentTime = 0;
    somTransicaoFinal.play().then(() => {
        somPendente = false;
    }).catch(error => {
        if (error.name !== 'NotAllowedError') {
            console.error('Não foi possível reproduzir o som de transição final.', error);
            leitorProgresso.textContent = 'Não foi possível reproduzir o som da transição final.';
        }
    });
}

function prepararAudio() {
    desbloquearMusicaFundo();
    desbloquearMusicaFinal();
    if (estagioAtual === 2) iniciarMusicaFundo();
    if (estagioAtual === 4) iniciarMusicaFinal();

    if (audioPreparado) {
        if (somPendente) tocarSomTransicaoFinal();
        return;
    }
    if (audioEmPreparacao) return;

    audioEmPreparacao = true;
    somTransicaoFinal.muted = true;
    somTransicaoFinal.play().then(() => {
        somTransicaoFinal.pause();
        somTransicaoFinal.currentTime = 0;
        somTransicaoFinal.muted = false;
        audioEmPreparacao = false;
        audioPreparado = true;
        if (somPendente) tocarSomTransicaoFinal();
    }).catch(error => {
        audioEmPreparacao = false;
        somTransicaoFinal.muted = false;
        if (somTransicaoFinal.error) {
            console.error('Não foi possível carregar o som de transição final.', error);
            leitorProgresso.textContent = 'Não foi possível carregar o som da transição final.';
        }
    });
}

async function detectarInicioAudivelMusica() {
    if (!window.AudioContext) {
        throw new Error('Este navegador não oferece suporte à análise de áudio Web Audio.');
    }

    const resposta = await fetch(musicaFundo.currentSrc || musicaFundo.src);
    if (!resposta.ok) {
        throw new Error(`Falha ao carregar a música para análise: HTTP ${resposta.status}.`);
    }

    const contexto = new AudioContext();
    try {
        const buffer = await contexto.decodeAudioData(await resposta.arrayBuffer());
        const tamanhoJanela = Math.max(1, Math.floor(buffer.sampleRate * 0.02));
        const janelas = [];
        let maiorRms = 0;

        for (let inicio = 0; inicio < buffer.length; inicio += tamanhoJanela) {
            const fim = Math.min(inicio + tamanhoJanela, buffer.length);
            let somaQuadrados = 0;
            let amostras = 0;
            for (let canal = 0; canal < buffer.numberOfChannels; canal++) {
                const dados = buffer.getChannelData(canal);
                for (let indice = inicio; indice < fim; indice++) {
                    somaQuadrados += dados[indice] * dados[indice];
                    amostras++;
                }
            }
            const rms = Math.sqrt(somaQuadrados / amostras);
            janelas.push(rms);
            maiorRms = Math.max(maiorRms, rms);
        }

        const limite = Math.max(0.0005, maiorRms * 0.015);
        for (let indice = 0; indice < janelas.length - 1; indice++) {
            if (janelas[indice] >= limite && janelas[indice + 1] >= limite) {
                return Math.max(0, indice * tamanhoJanela / buffer.sampleRate - 0.04);
            }
        }
        return 0;
    } finally {
        await contexto.close();
    }
}

function desbloquearMusicaFundo() {
    if (musicaDesbloqueada || musicaEmDesbloqueio || !musicaFundo.paused) return;

    musicaEmDesbloqueio = true;
    musicaFundo.muted = true;
    musicaFundo.play().then(() => {
        musicaFundo.pause();
        musicaFundo.currentTime = 0;
        musicaFundo.muted = false;
        musicaDesbloqueada = true;
        musicaEmDesbloqueio = false;
        if (estagioAtual === 2) iniciarMusicaFundo();
    }).catch(error => {
        musicaFundo.muted = false;
        musicaEmDesbloqueio = false;
        if (error.name !== 'NotAllowedError') {
            console.error('Não foi possível preparar a reprodução da música de fundo.', error);
        }
    });
}

async function iniciarMusicaFundo() {
    if (estagioAtual !== 2 || !musicaDesbloqueada || musicaEmInicio || !musicaFundo.paused) return;

    musicaEmInicio = true;
    try {
        const inicio = await inicioAudivelMusica;
        if (estagioAtual !== 2 || !musicaFundo.paused) return;
        musicaFundo.currentTime = inicio;
        musicaFundo.volume = 0;
        inicioReproducaoMusica = performance.now();
        await musicaFundo.play();
        ultimoTempoMusica = musicaFundo.currentTime;
    } catch (error) {
        inicioReproducaoMusica = undefined;
        console.error('Não foi possível iniciar a música no estágio 2.', error);
    } finally {
        musicaEmInicio = false;
    }
}

function pararMusicaFundo() {
    if (musicaFundo.paused) return;
    musicaFundo.pause();
    musicaFundo.currentTime = 0;
    musicaFundo.volume = 0;
    inicioReproducaoMusica = undefined;
}

function desbloquearMusicaFinal() {
    if (musicaFinalDesbloqueada || musicaFinalEmDesbloqueio || !musicaFaseFinal.paused) return;

    musicaFinalEmDesbloqueio = true;
    musicaFaseFinal.muted = true;
    musicaFaseFinal.play().then(() => {
        musicaFaseFinal.pause();
        musicaFaseFinal.currentTime = 0;
        musicaFaseFinal.muted = false;
        musicaFinalDesbloqueada = true;
        musicaFinalEmDesbloqueio = false;
        if (estagioAtual === 4) iniciarMusicaFinal();
    }).catch(error => {
        musicaFaseFinal.muted = false;
        musicaFinalEmDesbloqueio = false;
        if (error.name !== 'NotAllowedError') {
            console.error('Não foi possível preparar a música da fase final.', error);
            leitorProgresso.textContent = 'Não foi possível preparar a música da fase final.';
        }
    });
}

function aguardarMetadadosMusicaFinal() {
    if (musicaFaseFinal.readyState >= HTMLMediaElement.HAVE_METADATA) {
        return Promise.resolve();
    }
    return new Promise((resolve, reject) => {
        const aoCarregar = () => {
            limparListeners();
            resolve();
        };
        const aoFalhar = () => {
            limparListeners();
            reject(new Error('O arquivo sounds/background-music-final.mp3 não pôde ser carregado.'));
        };
        const limparListeners = () => {
            musicaFaseFinal.removeEventListener('loadedmetadata', aoCarregar);
            musicaFaseFinal.removeEventListener('error', aoFalhar);
        };
        musicaFaseFinal.addEventListener('loadedmetadata', aoCarregar, { once: true });
        musicaFaseFinal.addEventListener('error', aoFalhar, { once: true });
        musicaFaseFinal.load();
    });
}

async function iniciarMusicaFinal() {
    if (estagioAtual !== 4 || !musicaFinalDesbloqueada || musicaFinalEmInicio || !musicaFaseFinal.paused) return;

    musicaFinalEmInicio = true;
    try {
        await aguardarMetadadosMusicaFinal();
        if (musicaFaseFinal.duration <= 30) {
            throw new Error('A música da fase final precisa ter mais de 30 segundos.');
        }
        if (estagioAtual !== 4 || !musicaFaseFinal.paused) return;

        musicaFaseFinal.currentTime = 30;
        musicaFaseFinal.volume = 0;
        inicioReproducaoMusicaFinal = performance.now();
        await musicaFaseFinal.play();
    } catch (error) {
        inicioReproducaoMusicaFinal = undefined;
        console.error('Não foi possível iniciar a música da fase final.', error);
        leitorProgresso.textContent = 'Não foi possível iniciar a música da fase final.';
    } finally {
        musicaFinalEmInicio = false;
    }
}

function atualizarVolumeMusicaFinal() {
    if (musicaFaseFinal.paused) {
        quadroVolumeMusicaFinal = undefined;
        return;
    }

    const fadeIn = Math.min(1, (performance.now() - inicioReproducaoMusicaFinal) / (DURACAO_FADE_MUSICA * 1000));
    const fadeOut = Math.min(1, Math.max(0, musicaFaseFinal.duration - musicaFaseFinal.currentTime) / DURACAO_FADE_MUSICA);
    musicaFaseFinal.volume = 0.18 * Math.min(fadeIn, fadeOut);
    quadroVolumeMusicaFinal = window.requestAnimationFrame(atualizarVolumeMusicaFinal);
}

musicaFaseFinal.addEventListener('play', () => {
    if (quadroVolumeMusicaFinal === undefined) atualizarVolumeMusicaFinal();
});
musicaFaseFinal.addEventListener('pause', () => {
    if (quadroVolumeMusicaFinal !== undefined) {
        window.cancelAnimationFrame(quadroVolumeMusicaFinal);
        quadroVolumeMusicaFinal = undefined;
    }
});
musicaFaseFinal.addEventListener('ended', () => {
    if (estagioAtual !== 4) return;
    musicaFaseFinal.currentTime = 30;
    musicaFaseFinal.volume = 0;
    inicioReproducaoMusicaFinal = performance.now();
    musicaFaseFinal.play().catch(error => {
        console.error('Não foi possível repetir a música da fase final.', error);
        leitorProgresso.textContent = 'Não foi possível repetir a música da fase final.';
    });
});
musicaFaseFinal.addEventListener('error', () => {
    console.error('O arquivo de música da fase final não pôde ser carregado.');
});

function atualizarVolumeMusica() {
    if (musicaFundo.paused) {
        quadroVolumeMusica = undefined;
        return;
    }

    const duracao = musicaFundo.duration;
    const agora = performance.now();
    const tempo = musicaFundo.currentTime;
    if (tempo + 0.1 < ultimoTempoMusica) inicioReproducaoMusica = agora;
    ultimoTempoMusica = tempo;

    if (Number.isFinite(duracao) && duracao > 0) {
        const fadeIn = Math.min(1, (agora - inicioReproducaoMusica) / (DURACAO_FADE_MUSICA * 1000));
        const fadeOut = Math.min(1, Math.max(0, duracao - tempo) / DURACAO_FADE_MUSICA);
        musicaFundo.volume = VOLUME_MUSICA * Math.min(fadeIn, fadeOut);
    }

    quadroVolumeMusica = window.requestAnimationFrame(atualizarVolumeMusica);
}

musicaFundo.addEventListener('ended', () => {
    if (estagioAtual === 2) iniciarMusicaFundo();
});
musicaFundo.addEventListener('play', () => {
    if (quadroVolumeMusica === undefined) atualizarVolumeMusica();
});
musicaFundo.addEventListener('pause', () => {
    if (quadroVolumeMusica !== undefined) {
        window.cancelAnimationFrame(quadroVolumeMusica);
        quadroVolumeMusica = undefined;
    }
});

