function mostrarBolhaClique(evento) {
    const id = Number(evento?.id);
    const matiz = Number(evento?.hue);
    const x = Number(evento?.position_x);
    const y = Number(evento?.position_y);
    const tamanho = Number(evento?.size_px);
    if (!Number.isSafeInteger(id)
        || !Number.isInteger(matiz) || matiz < 0 || matiz > 359
        || !Number.isInteger(x) || x < 5 || x > 95
        || !Number.isInteger(y) || y < 5 || y > 95
        || !Number.isInteger(tamanho) || tamanho < 90 || tamanho > 180) {
        throw new Error('O Supabase retornou um evento de clique inválido.');
    }
    if (eventosBolhaExibidos.has(id)) return;
    eventosBolhaExibidos.add(id);

    const bolha = document.createElement('span');
    bolha.className = 'bolha-clique';
    bolha.style.setProperty('--bolha-matiz', String(matiz));
    bolha.style.setProperty('--bolha-x', `${x}%`);
    bolha.style.setProperty('--bolha-y', `${y}%`);
    bolha.style.setProperty('--bolha-tamanho', `${tamanho}px`);
    bolhasCliques.appendChild(bolha);
    while (bolhasCliques.childElementCount > 32) {
        bolhasCliques.firstElementChild.remove();
    }
    window.setTimeout(() => {
        bolha.remove();
        eventosBolhaExibidos.delete(id);
    }, reduzir ? 10000 : 6000);
}

function criarIconeMagia(arquivo, classe, configurar) {
    const icone = document.createElement('img');
    icone.className = classe;
    icone.src = `icones-magias/${arquivo}`;
    icone.alt = '';
    icone.draggable = false;
    icone.setAttribute('aria-hidden', 'true');
    configurar(icone);
    return icone;
}

function aplicarContornoColorido(icone) {
    const obterCorDominante = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 24;
        canvas.height = 24;
        const contexto = canvas.getContext('2d', { willReadFrequently: true });
        if (!contexto) {
            throw new Error('Não foi possível criar o canvas para colorir o contorno do ícone.');
        }
        contexto.drawImage(icone, 0, 0, canvas.width, canvas.height);

        const pixels = contexto.getImageData(0, 0, canvas.width, canvas.height).data;
        const cores = new Map();
        for (let i = 0; i < pixels.length; i += 4) {
            const [r, g, b, alpha] = pixels.slice(i, i + 4);
            if (alpha < 96) continue;

            const maximo = Math.max(r, g, b);
            const minimo = Math.min(r, g, b);
            const saturacao = maximo === 0 ? 0 : (maximo - minimo) / maximo;
            if (saturacao < 0.18) continue;

            const chave = [r, g, b].map(canal => Math.round(canal / 32)).join(',');
            const peso = alpha * saturacao;
            const acumulado = cores.get(chave) || { peso: 0, r: 0, g: 0, b: 0 };
            acumulado.peso += peso;
            acumulado.r += r * peso;
            acumulado.g += g * peso;
            acumulado.b += b * peso;
            cores.set(chave, acumulado);
        }

        let dominante = { peso: 0, r: 214, g: 210, b: 222 };
        for (const cor of cores.values()) {
            if (cor.peso > dominante.peso) dominante = cor;
        }
        const canal = nome => Math.round(dominante[nome] / dominante.peso);
        const corFinal = dominante.peso
            ? `rgba(${canal('r')}, ${canal('g')}, ${canal('b')}, 0.95)`
            : 'rgba(214, 210, 222, 0.95)';
        icone.style.setProperty('--runa-cor-contorno', corFinal);
    };

    if (icone.complete && icone.naturalWidth > 0) obterCorDominante();
    else icone.addEventListener('load', obterCorDominante, { once: true });
}

function adicionarEmLotes(tarefas, tamanhoLote = 5) {
    let indice = 0;
    function processarLote() {
        const limite = Math.min(indice + tamanhoLote, tarefas.length);
        while (indice < limite) tarefas[indice++]();
        if (indice < tarefas.length) {
            if (document.hidden) window.setTimeout(processarLote, 32);
            else requestAnimationFrame(processarLote);
        }
    }
    if (document.hidden) window.setTimeout(processarLote, 0);
    else requestAnimationFrame(processarLote);
}

function iniciarChuvaRunas() {
    runasChuva.replaceChildren();
    runasChuva.classList.add('ativa');

    const tarefas = ICONES_MAGIA.map((arquivo, indice) => () => {
        const icone = criarIconeMagia(arquivo, 'runa-chuva', elemento => {
            elemento.style.setProperty('--x', `${Math.random() * 96}%`);
            elemento.style.setProperty('--tamanho-chuva', `${76 + Math.random() * 52}px`);
            elemento.style.setProperty('--deriva', `${Math.random() * 24 - 12}vw`);
            elemento.style.setProperty('--rotacao-final', `${Math.random() * 540 - 270}deg`);
            elemento.style.setProperty('--queda-duracao', `${9 + Math.random() * 5}s`);
            elemento.style.setProperty('--queda-atraso', `${Math.random() * 13 + indice * 0.015}s`);
        });
        runasChuva.appendChild(icone);
    });
    adicionarEmLotes(tarefas);
}

function agendarChuvaRunas() {
    if (chuvaRunasAgendada || reduzir) return;
    chuvaRunasAgendada = true;

    window.setTimeout(() => {
        runasCentro.classList.add('sumindo');
        window.setTimeout(() => {
            runasCentro.replaceChildren();
            runasCentro.classList.remove('circulo-final', 'sumindo');
            iniciarChuvaRunas();
        }, 1400);
    }, 10000);
}

function mostrarRunas(estagio) {
    runasFlutuantes.replaceChildren();
    runasCentro.replaceChildren();
    runasFlutuantes.classList.remove('formando-circulo');
    const minimo = estagio === 2 ? 1 : 3;
    const maximo = estagio === 2 ? 2 : 5;
    const quantidade = minimo + Math.floor(Math.random() * (maximo - minimo + 1));
    const icones = [...ICONES_MAGIA];

    for (let i = icones.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [icones[i], icones[j]] = [icones[j], icones[i]];
    }

    const tarefas = [];
    for (let i = 0; i < quantidade; i++) {
        const lado = i % 2 === 0 ? 'esquerda' : 'direita';
        const x = lado === 'esquerda'
            ? 4 + Math.random() * 12
            : 84 + Math.random() * 12;
        const y = `${12 + Math.random() * 72}%`;
        const duracao = `${7 + Math.random() * 6}s`;
        const atraso = `${-Math.random() * 8}s`;
        const oscilacao = `${10 + Math.random() * 16}px`;
        tarefas.push(() => {
            const colorida = estagio === 2 ? ' colorida' : '';
            const icone = criarIconeMagia(icones[i], `runa-flutuante ${lado}${colorida}`, elemento => {
                elemento.style.setProperty('--x', `${x}%`);
                elemento.style.setProperty('--y', y);
                elemento.style.setProperty('--duracao', duracao);
                elemento.style.setProperty('--atraso', atraso);
                elemento.style.setProperty('--oscilacao', oscilacao);
            });
            if (estagio === 2) aplicarContornoColorido(icone);
            runasFlutuantes.appendChild(icone);
        });
    }
    adicionarEmLotes(tarefas);
}

function formarCirculoRunas() {
    runasFlutuantes.replaceChildren();
    runasCentro.replaceChildren();
    runasFlutuantes.classList.add('formando-circulo');

    const tarefas = ICONES_MAGIA.map((arquivo, indice) => () => {
        const angulo = (indice / ICONES_MAGIA.length) * 360 - 90;
        const icone = criarIconeMagia(arquivo, 'runa-flutuante runa-circulo', elemento => {
            elemento.style.setProperty('--angulo', `${angulo}deg`);
            elemento.style.setProperty('--atraso-formacao', `${indice * 0.045}s`);
            elemento.style.setProperty('--atraso-entrada', `${Math.random() * 0.8}s`);
            elemento.style.setProperty('--dx', `${(Math.random() - 0.5) * 90}vw`);
            elemento.style.setProperty('--dy', `${(Math.random() - 0.5) * 90}vh`);
        });
        runasFlutuantes.appendChild(icone);
    });
    adicionarEmLotes(tarefas);
}

function formarCirculoFinal() {
    runasFlutuantes.replaceChildren();
    runasCentro.replaceChildren();
    runasChuva.replaceChildren();
    runasChuva.classList.remove('ativa');
    runasFlutuantes.classList.remove('formando-circulo');
    runasCentro.classList.add('circulo-final');
    agendarChuvaRunas();

    const tarefas = ICONES_MAGIA.map((arquivo, indice) => () => {
        const anelExterno = indice % 2 === 1;
        const indiceNoAnel = Math.floor(indice / 2);
        const angulo = (indiceNoAnel / (ICONES_MAGIA.length / 2)) * 360
            + (anelExterno ? 180 / (ICONES_MAGIA.length / 2) : 0);
        const raio = imagem.clientWidth * (anelExterno ? 0.45 : 0.25);
        const tamanho = Math.min(34, Math.max(24, imagem.clientWidth * 0.075));
        const sentido = anelExterno ? -360 : 360;
        const entrada = document.createElement('span');
        const orbita = document.createElement('span');
        entrada.className = 'entrada-runa';
        entrada.style.setProperty('--dx', `${(Math.random() - 0.5) * 90}vw`);
        entrada.style.setProperty('--dy', `${(Math.random() - 0.5) * 90}vh`);
        entrada.style.setProperty('--atraso-entrada', `${indice * 0.035}s`);
        orbita.className = 'orbita-runa';
        orbita.style.setProperty('--angulo', `${angulo}deg`);
        orbita.style.setProperty('--contra-giro', `${-angulo}deg`);
        orbita.style.setProperty('--raio-orbita', `${raio}px`);
        orbita.style.setProperty('--tamanho-runa', `${tamanho}px`);
        orbita.style.setProperty('--giro-orbita', `${sentido}deg`);
        orbita.style.setProperty('--atraso-frente-verso', `${-indice * 0.19}s`);
        orbita.style.setProperty('--atraso-entrada', `${indice * 0.035}s`);
        orbita.style.setProperty('--duracao-orbita', anelExterno ? '24s' : '18s');
        const frenteVerso = document.createElement('span');
        frenteVerso.className = 'orientacao-runa';
        const icone = criarIconeMagia(arquivo, 'icone-magico', () => { });
        frenteVerso.appendChild(icone);
        orbita.appendChild(frenteVerso);
        entrada.appendChild(orbita);
        runasCentro.appendChild(entrada);
    });
    adicionarEmLotes(tarefas);
}

// Estado 2: segunda página já visível
function trocarDireto() {
    imagem.classList.add('trocada');
    ativarEfeitos();
    mostrarRunas(2);
}

// Estado 3: terceira página já visível, efeitos fortes
let extrasCriadas = false;
function ativarEfeitosFortes() {
    palco.classList.add('fortes');
    if (!extrasCriadas && !reduzir) {
        extrasCriadas = true;
        criarParticulas(PARTICULAS_EXTRAS, true);
    }
}
function finalDireto() {
    imagem.classList.add('trocada', 'mar-final');
    ativarEfeitos();
    ativarEfeitosFortes();
    formarCirculoRunas();
}

function finalQuartaDireto() {
    imagem.classList.add('trocada', 'mar-final', 'quarta-final');
    ativarEfeitos();
    ativarEfeitosFortes();
    formarCirculoFinal();
    iniciarMusicaFinal();
}

function iniciarQuarta() {
    if (reduzir || !quarta.complete) {
        finalQuartaDireto();
        return;
    }

    emAndamento = true;
    tremerPagina();
    formarCirculoFinal();
    imagem.classList.add('formando-quarta');

    window.setTimeout(() => {
        imagem.classList.remove('formando-quarta');
        imagem.classList.add('quarta-final');
        emAndamento = false;
        iniciarMusicaFinal();
    }, 5000);
}

function criarCanvas() {
    const w = imagem.offsetWidth, h = imagem.offsetHeight;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(w * dpr);
    canvas.height = Math.round(h * dpr);
    const ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    return { w, h, canvas, ctx };
}

// =====================================================================
//  1ª TROCA: tentáculos sobem de baixo e infectam a página
// =====================================================================
function gerarTentaculos(w, h) {
    const passo = h / 60;
    const ramos = [];

    function trilha(x, y, ang0, amp, omega, fase, maxPassos, t0, dt, baseR) {
        const pts = [{ x, y, tp: t0 }];
        let px = x, py = y;
        for (let i = 1; i <= maxPassos; i++) {
            const ang = ang0 + amp * Math.sin(omega * i + fase);
            px += Math.cos(ang) * passo;
            py += Math.sin(ang) * passo;
            pts.push({ x: px, y: py, tp: t0 + i * dt });
            if (py < -40) break;
        }
        return { pts, baseR, proximoSegmento: 1 };
    }

    for (let i = 0; i < TENTACULOS; i++) {
        const x0 = ((i + 0.5 + (Math.random() - 0.5) * 0.6) / TENTACULOS) * w;
        const t0 = Math.random() * 0.8;
        const dt = 0.035 + Math.random() * 0.02;
        const baseR = w * (0.009 + Math.random() * 0.008);
        const tronco = trilha(
            x0, h + 10, -Math.PI / 2,
            0.5 + Math.random() * 0.4,
            0.18 + Math.random() * 0.15,
            Math.random() * Math.PI * 2,
            95, t0, dt, baseR
        );
        ramos.push(tronco);

        const nb = 2 + Math.floor(Math.random() * 2);
        for (let b = 0; b < nb; b++) {
            const idx = 8 + Math.floor(Math.random() * 35);
            if (idx >= tronco.pts.length - 5) continue;
            const base = tronco.pts[idx];
            const lado = Math.random() < 0.5 ? -1 : 1;
            ramos.push(trilha(
                base.x, base.y, -Math.PI / 2 + lado * (0.7 + Math.random() * 0.5),
                0.6, 0.2 + Math.random() * 0.2, Math.random() * Math.PI * 2,
                12 + Math.floor(Math.random() * 22), base.tp, dt, baseR * 0.6
            ));
        }
    }
    return ramos;
}

function infectar() {
    if (reduzir || !antiga.complete) { trocarDireto(); return; }
    emAndamento = true;
    tremerPagina();

    const { w, h, canvas, ctx } = criarCanvas();
    ctx.drawImage(antiga, 0, 0, w, h);
    cascas.appendChild(canvas);
    antiga.style.visibility = 'hidden';

    imagem.classList.add('infectando');

    const ramos = gerarTentaculos(w, h);
    const CRESCE = w * 0.025;
    const MAXIMO = w * 0.11;
    const raio = (r, idade) =>
        Math.max(0.5, Math.min(MAXIMO, r.baseR * Math.min(1, idade / 0.4) + CRESCE * idade));

    const INICIO_ONDA = 1.2;
    const FIM_ONDA = DURACAO - 0.8;
    const t0 = performance.now();

    function quadro(agora) {
        const t = (agora - t0) / 1000;
        if (t >= DURACAO) {
            cascas.innerHTML = '';
            imagem.classList.remove('infectando');
            trocarDireto();
            emAndamento = false;
            return;
        }

        ctx.globalCompositeOperation = 'source-atop';
        ctx.strokeStyle = 'rgba(18, 0, 0, 0.45)';
        for (const r of ramos) {
            while (r.proximoSegmento < r.pts.length) {
                const i = r.proximoSegmento;
                const p = r.pts[i];
                if (p.tp > t) break;
                r.proximoSegmento++;
                const rad = raio(r, t - p.tp);
                ctx.lineWidth = 2 * (rad + 4 + rad * 0.3);
                ctx.beginPath();
                ctx.moveTo(r.pts[i - 1].x, r.pts[i - 1].y);
                ctx.lineTo(p.x, p.y);
                ctx.stroke();
                ctx.lineWidth = 2 * raio(r, t - p.tp);
                ctx.globalCompositeOperation = 'destination-out';
                ctx.beginPath();
                ctx.moveTo(r.pts[i - 1].x, r.pts[i - 1].y);
                ctx.lineTo(p.x, p.y);
                ctx.stroke();
                ctx.globalCompositeOperation = 'source-atop';
            }
        }

        if (t > INICIO_ONDA) {
            const prog = Math.min(1, (t - INICIO_ONDA) / (FIM_ONDA - INICIO_ONDA));
            const fy = h + 30 - prog * (h + 90);
            const onda = x => fy + 12 * Math.sin(x * 0.045 + t * 2.5) + 8 * Math.sin(x * 0.11 - t * 1.7);
            ctx.strokeStyle = 'rgba(18, 0, 0, 0.35)';
            ctx.lineWidth = 40;
            ctx.beginPath();
            for (let x = 0; x <= w + 10; x += 10) {
                if (x === 0) ctx.moveTo(x, onda(x)); else ctx.lineTo(x, onda(x));
            }
            ctx.stroke();
            ctx.globalCompositeOperation = 'destination-out';
            ctx.fillStyle = '#000';
            ctx.beginPath();
            ctx.moveTo(0, h + 20);
            for (let x = 0; x <= w + 10; x += 10) ctx.lineTo(x, onda(x));
            ctx.lineTo(w + 10, h + 20);
            ctx.closePath();
            ctx.fill();
        }

        ctx.globalCompositeOperation = 'source-over';

        requestAnimationFrame(quadro);
    }
    requestAnimationFrame(quadro);
}

// =====================================================================
//  2ª TROCA: o mar sobe, inunda a página e a terceira página emerge
// =====================================================================
function inundar() {
    if (reduzir || !terceira.complete) { finalDireto(); return; }
    emAndamento = true;
    tremerPagina();

    const { w, h, canvas, ctx } = criarCanvas();
    mar.appendChild(canvas);

    const nw = terceira.naturalWidth, nh = terceira.naturalHeight;
    const A1 = w * 0.03, A2 = w * 0.018, A3 = w * 0.008;
    const FY_FIM = -120;   // superfície fora do topo = tudo coberto

    // altura da superfície da água no ponto x (3 ondas somadas)
    const superficie = (x, t, fy, fase) => {
        const fx = (x / w) * Math.PI * 2;
        return fy
            + A1 * (Math.sin(fx * 0.72 + t * 0.62 + fase)
                + 0.42 * Math.sin(fx * 1.9 - t * 0.48 + fase * 1.7))
            + A2 * Math.sin(fx * 4.1 - t * 1.1 + fase)
            + A3 * (Math.sin(fx * 9.3 + t * 1.8) + 0.45 * Math.sin(fx * 15 - t));
    };

    function tracar(t, fy, fase) {
        ctx.beginPath();
        ctx.moveTo(0, superficie(0, t, fy, fase));
        for (let x = 8; x <= w + 8; x += 8) ctx.lineTo(x, superficie(x, t, fy, fase));
        ctx.lineTo(w + 8, h + 20);
        ctx.lineTo(0, h + 20);
        ctx.closePath();
    }

    function tracarSuperficie(t, fy, fase, deslocamento = 0) {
        ctx.beginPath();
        for (let x = 0; x <= w + 8; x += 8) {
            const y = superficie(x, t, fy, fase) + deslocamento;
            if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
        }
    }

    function desenharAgua(t, fy, alfa, espuma) {
        if (alfa <= 0.001) return;
        ctx.save();
        ctx.globalAlpha = alfa;

        tracar(t * 0.72, fy - w * 0.045, 1.7);
        ctx.fillStyle = 'rgba(255, 255, 255, 0.24)';
        ctx.fill();

        const grad = ctx.createLinearGradient(0, fy, 0, fy + h * 0.9);
        grad.addColorStop(0, 'rgb(255, 255, 255)');
        grad.addColorStop(0.2, 'rgb(246, 247, 248)');
        grad.addColorStop(0.62, 'rgb(223, 226, 230)');
        grad.addColorStop(1, 'rgb(194, 199, 206)');
        tracar(t, fy, 0);
        ctx.fillStyle = grad;
        ctx.fill();

        ctx.save();
        ctx.clip();
        const sombra = ctx.createLinearGradient(0, fy, 0, fy + h * 0.28);
        sombra.addColorStop(0, 'rgba(77, 83, 94, 0.22)');
        sombra.addColorStop(0.16, 'rgba(105, 111, 121, 0.11)');
        sombra.addColorStop(1, 'rgba(105, 111, 121, 0)');
        ctx.fillStyle = sombra;
        ctx.fillRect(0, fy, w, h);

        ctx.strokeStyle = 'rgba(106, 113, 124, 0.12)';
        ctx.lineWidth = 1;
        for (let j = 0; j < 6; j++) {
            ctx.beginPath();
            for (let x = 0; x <= w + 12; x += 12) {
                const y = fy + (j + 1) * h * 0.14
                    + 11 * Math.sin(x * 0.018 + t * 0.43 + j * 1.7)
                    + 4 * Math.sin(x * 0.052 - t * 0.72 + j);
                if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.stroke();
        }
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.34)';
        ctx.lineWidth = 1.5;
        for (let j = 0; j < 3; j++) {
            ctx.beginPath();
            for (let x = 0; x <= w + 12; x += 12) {
                const y = fy + (j + 1) * h * 0.22
                    + 7 * Math.sin(x * 0.021 - t * 0.34 + j * 2)
                    + 2 * Math.sin(x * 0.06 + t * 0.5);
                if (x === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.stroke();
        }
        ctx.restore();

        if (espuma) {
            ctx.save();
            ctx.lineCap = 'round';
            tracarSuperficie(t, fy, 0, w * 0.016);
            ctx.strokeStyle = 'rgba(81, 87, 98, 0.24)';
            ctx.lineWidth = w * 0.035;
            ctx.filter = 'blur(8px)';
            ctx.stroke();

            ctx.filter = 'none';
            tracarSuperficie(t, fy, 0);
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.68)';
            ctx.lineWidth = Math.max(1.5, w * 0.005);
            ctx.stroke();

            ctx.strokeStyle = 'rgba(255, 255, 255, 0.42)';
            ctx.lineWidth = Math.max(1, w * 0.002);
            for (let i = 0; i < 12; i++) {
                const x = ((i * 97 + t * (18 + i % 4 * 5)) % (w + 36)) - 18;
                const largura = w * (0.025 + (i % 3) * 0.012);
                const y = superficie(x, t, fy, 0) - w * 0.008;
                ctx.beginPath();
                ctx.moveTo(x, y);
                ctx.lineTo(x + largura, superficie(x + largura, t, fy, 0) - w * 0.008);
                ctx.stroke();
            }
            ctx.restore();
        }
        ctx.restore();
    }

    let revelando = false;
    const t0 = performance.now();

    function quadro(agora) {
        const t = (agora - t0) / 1000;
        ctx.clearRect(0, 0, w, h);

        if (t >= SUBIDA_MAR + REVELACAO) {
            mar.innerHTML = '';
            imagem.classList.remove('revelando');
            imagem.classList.add('mar-final');
            emAndamento = false;
            return;
        }

        if (t < SUBIDA_MAR) {
            // Fase 1: o mar sobe de baixo para cima
            const u = t / SUBIDA_MAR;
            const prog = (1 - Math.cos(Math.PI * u)) / 2;
            const fy = h + 40 - prog * (h + 40 - FY_FIM);
            desenharAgua(t, fy, 0.92, true);
        } else {
            // Fase 2: a água clareia e a terceira página emerge, com os efeitos fortes
            if (!revelando) {
                revelando = true;
                ativarEfeitosFortes();
                formarCirculoRunas();
                imagem.classList.add('revelando');
            }
            let k = (t - SUBIDA_MAR) / REVELACAO;
            k = k * k * (3 - 2 * k);
            const amp = w * 0.03 * (1 - k);
            const faixa = 3;
            ctx.save();
            ctx.beginPath();
            ctx.arc(w / 2, h / 2, Math.hypot(w / 2, h / 2) * k, 0, Math.PI * 2);
            ctx.clip();
            for (let y = 0; y < h; y += faixa) {
                const sy = (y * nh) / h;
                const sh = (faixa * nh) / h + 0.5;
                const dx = amp * Math.sin(y * 0.05 + t * 4);
                ctx.drawImage(terceira, 0, sy, nw, sh, dx - amp, y, w + 2 * amp, faixa + 0.5);
            }
            ctx.restore();
            desenharAgua(t, FY_FIM, 0.92 * (1 - k), false);
        }
        requestAnimationFrame(quadro);
    }
    requestAnimationFrame(quadro);
}

// =====================================================================
//  Partículas brancas (invisíveis até a segunda imagem aparecer)
// =====================================================================
function criarParticulas(qtd, forte) {
    for (let i = 0; i < qtd; i++) {
        const p = document.createElement('div');
        p.className = 'particula' + (forte ? ' forte' : '');
        p.style.setProperty('--x', (Math.random() * 100) + '%');
        p.style.setProperty('--t', (forte ? 4 + Math.random() * 6 : 2 + Math.random() * 5) + 'px');
        p.style.setProperty('--d', (forte ? 6 + Math.random() * 8 : 10 + Math.random() * 14) + 's');
        p.style.setProperty('--atraso', (-Math.random() * 14) + 's');
        p.style.setProperty('--bal', (Math.random() * 80 - 40) + 'px');
        const el = Math.random() < 0.5 ? 'particulas-atras' : 'particulas-frente';
        document.getElementById(el).appendChild(p);
    }
}
if (!reduzir) criarParticulas(PARTICULAS, false);

function validarProgressoGlobal(progresso) {
    if (!progresso || typeof progresso !== 'object') {
        throw new Error('O Supabase retornou um progresso global inválido.');
    }
    const cliques = Number(progresso.click_count);
    const estagio = Number(progresso.stage);
    if (!Number.isSafeInteger(cliques) || cliques < 0
        || !Number.isInteger(estagio) || estagio < 1 || estagio > 4) {
        throw new Error('O Supabase retornou cliques ou estágio global inválido.');
    }
    return { cliques, estagio };
}

function atualizarProgressoGlobal(progresso, inicial = false) {
    const validado = validarProgressoGlobal(progresso);
    totalGlobal = Math.max(totalGlobal, validado.cliques);
    const novoEstagio = Math.max(estagioSolicitado, validado.estagio);

    if (inicial) {
        estagioAtual = novoEstagio;
        estagioSolicitado = novoEstagio;
        if (novoEstagio === 2) {
            trocarDireto();
            iniciarMusicaFundo();
        }
        else if (novoEstagio === 3) finalDireto();
        else if (novoEstagio === 4) finalQuartaDireto();
    } else {
        estagioSolicitado = Math.max(estagioSolicitado, novoEstagio);
        processarAvanco();
    }

    const totalFormatado = totalGlobal.toLocaleString('pt-BR');
    contadorGlobal.textContent = `Cliques globais: ${totalFormatado}`;
    leitorProgresso.textContent = `Cliques globais: ${totalFormatado}. Estágio ${estagioSolicitado}.`;
}

function processarAvanco() {
    if (emAndamento || estagioAtual >= estagioSolicitado) return;

    estagioAtual++;

    if (estagioAtual === 2) {
        iniciarMusicaFundo();
        infectar();
    } else if (estagioAtual === 3) {
        pararMusicaFundo();
        inundar();
    } else if (estagioAtual === 4) {
        pararMusicaFundo();
        tocarSomTransicaoFinal();
        iniciarQuarta();
    }
}

botaoClique.addEventListener('click', async () => {
    if (!supabaseClient || botaoClique.disabled) return;
    const inicioRegistro = Date.now();
    botaoClique.disabled = true;
    try {
        const { data, error } = await supabaseClient.rpc('register_global_click', {
            p_visitor_id: identidadeVisitante.id,
            p_hue: identidadeVisitante.hue,
            p_position_x: 5 + Math.floor(Math.random() * 91),
            p_position_y: 5 + Math.floor(Math.random() * 91),
            p_size_px: 100 + Math.floor(Math.random() * 81)
        });
        if (error) throw error;
        mostrarBolhaClique(data.event);
        atualizarProgressoGlobal(data);
        canalContador.send({
            type: 'broadcast',
            event: 'click-bubble',
            payload: { event: data.event }
        }).then(status => {
            if (status !== 'ok') {
                console.error(`A bolha foi registrada, mas o broadcast falhou: ${status}.`);
            }
        }).catch(error => {
            console.error('A bolha foi registrada, mas não foi possível transmiti-la aos outros visitantes.', error);
        });
    } catch (error) {
        console.error('Não foi possível registrar o clique global no Supabase.', error);
        leitorProgresso.textContent = 'Erro ao registrar o clique. Verifique a conexão e tente novamente.';
    } finally {
        const tempoRestante = Math.max(0, INTERVALO_MINIMO_CLIQUE_MS - (Date.now() - inicioRegistro));
        window.setTimeout(() => {
            botaoClique.disabled = false;
        }, tempoRestante);
    }
});

async function conectarContadorGlobal() {
    if (canalContador) await supabaseClient.removeChannel(canalContador);
    canalContador = supabaseClient
        .channel('contador-global', {
            config: {
                private: false,
                broadcast: { self: false }
            }
        })
        .on('postgres_changes', {
            event: 'UPDATE',
            schema: 'public',
            table: 'global_progress',
            filter: 'singleton_id=eq.1'
        }, () => {
            consultarProgressoGlobal().catch(error => {
                console.error('Não foi possível ler o estágio global atualizado pelo Supabase.', error);
                leitorProgresso.textContent = 'Erro ao ler a contagem global atualizada.';
            });
        })
        .on('broadcast', { event: 'click-bubble' }, ({ payload }) => {
            try {
                mostrarBolhaClique(payload.event);
            } catch (error) {
                console.error('Não foi possível mostrar a bolha de um clique global.', error);
            }
        })
        .subscribe(status => {
            if (status === 'CHANNEL_ERROR' || status === 'TIMED_OUT' || status === 'CLOSED') {
                const error = new Error(`Canal Realtime do Supabase indisponível: ${status}`);
                console.error(error);
                leitorProgresso.textContent = 'Conexão em tempo real indisponível.';
            }
        });

    try {
        await consultarProgressoGlobal(true);
    } catch (error) {
        await supabaseClient.removeChannel(canalContador);
        canalContador = undefined;
        throw error;
    }

    botaoClique.disabled = false;
}

async function consultarProgressoGlobal(inicial = false) {
    const { data, error } = await supabaseClient.rpc('get_global_progress');
    if (error) throw error;
    atualizarProgressoGlobal(data, inicial);
}

if (window.supabase) {
    supabaseClient = window.supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
    conectarContadorGlobal().catch(error => {
        console.error('Não foi possível conectar ao contador global de cliques.', error);
        leitorProgresso.textContent = 'Contador global indisponível. Verifique a conexão com o Supabase.';
        botaoClique.disabled = true;
    });
} else {
    console.error('A biblioteca Supabase não foi carregada.');
    leitorProgresso.textContent = 'Contador global indisponível. Recarregue a página para tentar novamente.';
    botaoClique.disabled = true;
}

window.setInterval(processarAvanco, 100);